def subtract(a, b):
    # Filter out empty intervals and merge overlapping intervals
    def merge_intervals(intervals):
        if not intervals:
            return []

        # Filter out empty intervals (start >= end)
        valid = [iv for iv in intervals if iv[0] < iv[1]]

        if not valid:
            return []

        # Sort by start position
        valid.sort()

        merged = [valid[0]]
        for start, end in valid[1:]:
            if start <= merged[-1][1]:
                # Overlapping or touching, merge
                merged[-1][1] = max(merged[-1][1], end)
            else:
                # Non-overlapping, add new interval
                merged.append([start, end])

        return merged

    # Merge input intervals
    a_merged = merge_intervals(a)
    b_merged = merge_intervals(b)

    if not a_merged:
        return []

    if not b_merged:
        return a_merged

    # Subtract b from a
    result = []

    for a_start, a_end in a_merged:
        current_intervals = [[a_start, a_end]]

        for b_start, b_end in b_merged:
            new_intervals = []
            for curr_start, curr_end in current_intervals:
                # No overlap
                if b_end <= curr_start or b_start >= curr_end:
                    new_intervals.append([curr_start, curr_end])
                else:
                    # Overlap exists, split the current interval
                    if curr_start < b_start:
                        new_intervals.append([curr_start, b_start])
                    if b_end < curr_end:
                        new_intervals.append([b_end, curr_end])
            current_intervals = new_intervals

        result.extend(current_intervals)

    # Sort and merge touching intervals in result
    if not result:
        return []

    result.sort()
    final = [result[0]]
    for start, end in result[1:]:
        if start <= final[-1][1]:
            final[-1][1] = max(final[-1][1], end)
        else:
            final.append([start, end])

    return final

